    37	function calculateAmount(numberOfParticipants: number, total: number, currency: string, isDefaultUser = false): number {
    38	    // Since the backend can maximum store 2 decimal places, any currency with more than 2 decimals
    39	    // has to be capped to 2 decimal places
    40	    const currencyUnit = Math.min(100, CurrencyUtils.getCurrencyUnit(currency));
    41	    const totalInCurrencySubunit = Math.round((total / 100) * currencyUnit);
    42	    const totalParticipants = numberOfParticipants + 1;
    43	    const amountPerPerson = Math.round(totalInCurrencySubunit / totalParticipants);
    44	    let finalAmount = amountPerPerson;
    45	    if (isDefaultUser) {
    46	        const sumAmount = amountPerPerson * totalParticipants;
    47	        const difference = totalInCurrencySubunit - sumAmount;
    48	        finalAmount = totalInCurrencySubunit !== sumAmount ? amountPerPerson + difference : amountPerPerson;
    49	    }
    50	    return Math.round((finalAmount * 100) / currencyUnit);
